def solve_s_max():
    n_values = [1, 2, 3, 4]
    p_range = range(1, 11)
    q_range = range(1, 11)

    results = {}

    print("--- Maximum S found for n=1 to n=4 (p, q <= 10) ---")

    for n in n_values:
        max_S_n = -float('inf')
        found_solution = False

        for p in p_range:
            for q in q_range:
                # S = (12 + n) / p + (13 - n) / q
                try:
                    S = (12 + n) / p + (13 - n) / q
                except ZeroDivisionError:
                    # Should not happen since p, q start from 1
                    continue

                # Constraint: S < 1
                if S < 1:
                    found_solution = True
                    if S > max_S_n:
                        max_S_n = S

        if found_solution:
            print(f"For n={n}: Maximum S found is {max_S_n}")
            results[n] = max_S_n
        else:
            print(f"For n={n}: No solution found such that S < 1 with p, q <= 10.")
            results[n] = None

    return results

solve_s_max()

def calculate_S(n, p, q):
    if p <= 0 or q <= 0:
        return -float('inf')
    A = 12 + n
    B = 13 - n
    return A / p + B / q

